using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Linq;using System.Windows.Forms;
namespace IDSketcher{
partial class Canvas{
 public void TestCanvasSampling(){
  using(var doc=new Document("A4",100)){var previous=Doc;Doc=doc;Size=new Size(600,400);Zoom=2.35f;Offset=PointF.Empty;ViewAngle=0;ClearScreenLayers();using(var g=Graphics.FromImage(doc.Selected.Image)){g.SmoothingMode=SmoothingMode.None;g.FillPolygon(Brushes.Black,new[]{new Point(20,20),new Point(210,110),new Point(20,110)});}doc.Selected.InvalidateVectors();byte[] source=Document.Png(doc.Selected.Image);
   using(var image=new Bitmap(600,400))using(var g=Graphics.FromImage(image)){g.Clear(Color.White);PaintCachedDocument(g);int greys=0;for(int y=0;y<350;y++)for(int x=0;x<550;x++){int v=image.GetPixel(x,y).R;if(v>0&&v<255)greys++;}if(greys<100)throw new Exception("Enlarged pixels must use smooth sampling");image.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"smooth-pixel-sampling.png"));}if(!source.SequenceEqual(Document.Png(doc.Selected.Image)))throw new Exception("View smoothing changed document pixels");
   using(var draw=Graphics.FromImage(doc.Selected.Image))draw.FillRectangle(Brushes.Red,60,45,15,10);doc.Selected.UpdatePixelAdjustment(new Rectangle(60,45,15,10));using(var partial=new Bitmap(600,400))using(var full=new Bitmap(600,400)){using(var g=Graphics.FromImage(partial)){g.Clear(Color.White);PaintCachedDocument(g);}ClearScreenLayers();using(var g=Graphics.FromImage(full)){g.Clear(Color.White);PaintCachedDocument(g);}if(!Document.Png(partial).SequenceEqual(Document.Png(full))){int max=0,count=0,xx=0,yy=0;for(int y=0;y<400;y++)for(int x=0;x<600;x++){var a=partial.GetPixel(x,y);var b=full.GetPixel(x,y);int d=Math.Max(Math.Abs(a.R-b.R),Math.Max(Math.Abs(a.G-b.G),Math.Abs(a.B-b.B)));if(d>0)count++;if(d>max){max=d;xx=x;yy=y;}}if(max>3)throw new Exception("Smooth partial repaint differs: max="+max+" count="+count+" location="+xx+","+yy);}}
   using(var g=Graphics.FromImage(doc.Selected.Image))g.Clear(Color.Transparent);doc.Selected.IsVector=true;var shape=new VectorShape{Kind="Line",Width=1.1f,Opacity=.7f,Colour=Color.Black,Points=new System.Collections.Generic.List<PointF>{new PointF(20.25f,30.4f),new PointF(210.6f,120.8f)}};doc.Selected.Vectors.Add(shape);doc.Selected.InvalidateVectors();
   foreach(float angle in new[]{0f,23f}){ViewAngle=angle;ClearScreenLayers();using(var actual=new Bitmap(600,400))using(var expected=new Bitmap(600,400)){using(var g=Graphics.FromImage(actual)){g.Clear(Color.White);PaintCachedDocument(g);}using(var g=Graphics.FromImage(expected)){g.Clear(Color.White);ApplyViewRotation(g);g.TranslateTransform(Offset.X,Offset.Y);g.ScaleTransform(Zoom,Zoom);ConfigureViewSampling(g);shape.Draw(g);}int worst=0;for(int y=0;y<400;y++)for(int x=0;x<600;x++)worst=Math.Max(worst,Math.Abs(actual.GetPixel(x,y).R-expected.GetPixel(x,y).R));if(worst>3)throw new Exception("Vector view must match native resolution geometry: "+worst);if(angle==0)actual.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"smooth-vector-sampling.png"));}}
   ClearScreenLayers();Doc=previous;ViewAngle=0;
  }
 }
 int ViewSamplingPadding{get{return Math.Max(4,(int)Math.Ceiling(2*Zoom)+2);}}
 void ConfigureViewSampling(Graphics g){g.InterpolationMode=Math.Abs(Zoom-1)<.00001&&Math.Abs(ViewAngle)<.00001?InterpolationMode.NearestNeighbor:InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.Half;g.SmoothingMode=SmoothingMode.AntiAlias;}
 void PaintViewLayer(Graphics g,Layer layer){
  ConfigureViewSampling(g);bool direct=layer.IsVector&&layer.Adjustment.Identity;var source=direct?layer.Image:layer.Rendered();using(var attributes=new ImageAttributes()){attributes.SetWrapMode(WrapMode.TileFlipXY);g.DrawImage(source,new Rectangle(0,0,Doc.Width,Doc.Height),0,0,Doc.Width,Doc.Height,GraphicsUnit.Pixel,attributes);}
  if(direct){g.CompositingMode=CompositingMode.SourceOver;foreach(var shape in layer.Vectors)shape.Draw(g);}
 }
 void PaintPanDocument(Graphics g){g.SmoothingMode=SmoothingMode.AntiAlias;g.InterpolationMode=InterpolationMode.HighQualityBicubic;foreach(var layer in Doc.Layers){if(!layer.Visible||layer.Opacity<=0||layer.PermanentlyLocked)continue;if(layer.IsVector&&layer.Adjustment.Identity&&layer.Opacity>=1){g.DrawImage(layer.Image,new Rectangle(0,0,Doc.Width,Doc.Height));foreach(var shape in layer.Vectors)shape.Draw(g);}else Document.DrawLayer(g,layer);}}
}
partial class Studio{
 public void TestCentredSetupAndCanvasQuality(){
  previewing=true;Show();WindowState=FormWindowState.Normal;ClientSize=new Size(SharpDpi.Px(this,1200),SharpDpi.Px(this,800));Location=new Point(Screen.FromControl(this).WorkingArea.Left+40,Screen.FromControl(this).WorkingArea.Top+40);
  using(var dialog=new Setup()){dialog.Opacity=0;dialog.ShowInTaskbar=false;dialog.Show(this);Application.DoEvents();if(Math.Abs(dialog.Left+dialog.Width/2-(Left+Width/2))>1||Math.Abs(dialog.Top+dialog.Height/2-(Top+Height/2))>1)throw new Exception("New canvas centred after DPI scaling");using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"centred-new-canvas-preview.png"));}dialog.Close();}
  bool modalCentred=false;using(var modal=new Setup{Owner=this}){modal.Opacity=0;modal.ShowInTaskbar=false;modal.Shown+=delegate{modal.BeginInvoke((Action)delegate{modalCentred=Math.Abs(modal.Left+modal.Width/2-(Left+Width/2))<=1&&Math.Abs(modal.Top+modal.Height/2-(Top+Height/2))<=1;modal.Close();});};modal.ShowDialog(this);}if(!modalCentred)throw new Exception("Modal new canvas owner centre");WindowState=FormWindowState.Maximized;Application.DoEvents();using(var dialog=new Setup()){dialog.Opacity=0;dialog.ShowInTaskbar=false;dialog.Show(this);Application.DoEvents();if(Math.Abs(dialog.Left+dialog.Width/2-(Left+Width/2))>1||Math.Abs(dialog.Top+dialog.Height/2-(Top+Height/2))>1)throw new Exception("Startup maximised owner dialog centre");dialog.Close();}using(var view=new Canvas())view.TestCanvasSampling();dirty=false;
 }
}
}
